// ─── Answer Scrambler ─────────────────────────────────────────────────────────
// All questions are written with the correct answer at index 0 (c:0).
// This function redistributes the correct answer across A/B/C/D positions
// deterministically so users see varied answer positions every time.
function scrambleAnswers(questions) {
  return questions.map((item, i) => {
    const target = i % 4;           // 0→A, 1→B, 2→C, 3→D
    if (target === item.c) return item; // already in target slot
    const opts = [...item.opts];
    // Swap correct answer from its current slot (item.c) to target slot
    [opts[item.c], opts[target]] = [opts[target], opts[item.c]];
    return { ...item, opts, c: target };
  });
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

// Get all topics for a category
export function getTopics(categoryId) {
  const cat = PRACTICE_CATEGORIES.find(c => c.id === categoryId);
  return cat ? cat.topics : [];
}

// Get questions for a topic (answers scrambled for variety, guaranteed 30 questions)
export function getQuestions(categoryId, topicId) {
  const key = `${categoryId}/${topicId}`;
  let raw = PRACTICE_QUESTIONS[key] || QUANTITATIVE_QUESTIONS[key] || [];

  // If questions are not yet statically defined for this topic, generate 30 high quality questions
  if (!raw || raw.length === 0) {
    const topics = getTopics(categoryId);
    const matched = topics.find(t => t.id === topicId);
    raw = generateQuestionsForTopic(categoryId, topicId, matched ? matched.name : "");
  }

  return scrambleAnswers(raw);
}

// Get category by id
export function getCategory(categoryId) {
  return PRACTICE_CATEGORIES.find(c => c.id === categoryId) || null;
}
